rng=np.random.default_rng(742);n=250;v=np.r_[np.full(80,.008),np.full(55,.028),np.full(115,.011)];ret=rng.normal(0,v);roll=np.sqrt(np.convolve(ret**2,np.ones(15)/15,'same'))*np.sqrt(252);ax.plot(roll*100,color=ACCENT,label='realized rolling vol');ax.axhline(np.mean(v)*np.sqrt(252)*100,color=WARM,ls='--',label='one constant σ');ax.set_xlabel('Trading day');ax.set_ylabel('Annualized volatility (%)');ax.set_title('A single volatility misses regimes',loc='left');ax.legend()
